//! Golden-vector tests: the Rust core must match the Dart `doc_engine`
//! reference implementation byte-for-byte. Golden files live in
//! `rust/golden/` and were generated by the real Dart engine
//! (see `rust/golden/regenerate.md`).

use std::fs;
use std::path::PathBuf;

use doc_core::model::Document;
use doc_core::export_markdown;

fn golden(name: &str) -> Vec<u8> {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../golden")
        .join(name);
    fs::read(&path).unwrap_or_else(|e| panic!("cannot read {}: {e}", path.display()))
}

#[test]
fn golden_json_round_trip_is_byte_identical() {
    let bytes = golden("document.json");
    let text = String::from_utf8(bytes.clone()).expect("golden json is UTF-8");
    let doc = Document::from_json(&text).expect("golden json parses");
    let reserialized = doc.to_json();
    assert_eq!(
        reserialized.as_bytes(),
        bytes.as_slice(),
        "re-serialized JSON must be byte-identical to the Dart golden file"
    );
}

#[test]
fn golden_markdown_export_is_byte_identical() {
    let json = String::from_utf8(golden("document.json")).unwrap();
    let doc = Document::from_json(&json).unwrap();
    let md = export_markdown(&doc);
    assert_eq!(
        md.as_bytes(),
        golden("document.md").as_slice(),
        "Markdown export must be byte-identical to the Dart golden file"
    );
}

#[test]
fn golden_fixture_shape() {
    let json = String::from_utf8(golden("document.json")).unwrap();
    let doc = Document::from_json(&json).unwrap();
    assert_eq!(doc.title, "Spec");
    assert_eq!(doc.sections.len(), 1);
    let blocks: Vec<_> = doc.all_blocks().collect();
    assert_eq!(blocks.len(), 3);
    assert_eq!(blocks[0].plain_text(), "Intro");
    assert_eq!(blocks[1].plain_text(), "Hello world");
}

#[test]
fn malformed_json_is_rejected() {
    assert!(Document::from_json("{not json").is_err());
    assert!(Document::from_json("").is_err());
    // Valid JSON, wrong field types.
    assert!(Document::from_json(r#"{"id":1}"#).is_err());
    // Unknown block type.
    assert!(Document::from_json(
        r#"{"id":"d","title":"t","created_at":1,"updated_at":1,"deleted_at":null,"sync_status":"local_only","sections":[{"id":"s","blocks":[{"id":"b","type":"nope","inlines":[]}]}],"comments":[],"suggestions":[]}"#
    )
    .is_err());
    // Unknown mark.
    assert!(Document::from_json(
        r#"{"id":"d","title":"t","created_at":1,"updated_at":1,"deleted_at":null,"sync_status":"local_only","sections":[{"id":"s","blocks":[{"id":"b","type":"paragraph","inlines":[{"text":"x","marks":["sparkly"]}]}]}],"comments":[],"suggestions":[]}"#
    )
    .is_err());
}

#[test]
fn marks_are_sorted_on_reserialization() {
    // Dart sorts mark names; the Rust BTreeSet must produce the same order
    // regardless of input order.
    let input = r#"{"id":"d","title":"t","created_at":1,"updated_at":1,"deleted_at":null,"sync_status":"local_only","sections":[{"id":"s","blocks":[{"id":"b","type":"paragraph","inlines":[{"text":"x","marks":["italic","bold"]}]}]}],"comments":[],"suggestions":[]}"#;
    let doc = Document::from_json(input).unwrap();
    assert!(doc.to_json().contains(r#""marks":["bold","italic"]"#));
}

#[test]
fn table_and_image_blocks_parse() {
    // Minimal Phase-1 block kinds: they must parse and re-serialize, and
    // the Markdown mapping must hold.
    let input = r#"{"id":"d","title":"","created_at":1,"updated_at":1,"deleted_at":null,"sync_status":"local_only","sections":[{"id":"s","blocks":[{"id":"t","type":"table","inlines":[{"text":"","marks":[]}],"table_rows":[[{"inlines":[{"text":"a|b","marks":[]}]}]]},{"id":"i","type":"image","inlines":[{"text":"","marks":[]}],"image":{"asset_id":"asset-1","alt":"pic","byte_length":12,"hash":null}}]}],"comments":[],"suggestions":[]}"#;
    let doc = Document::from_json(input).unwrap();
    assert_eq!(doc.to_json(), input);
    assert_eq!(export_markdown(&doc), "| a\\|b |\n\n![pic](asset:asset-1)\n");
}
